"use strict";(globalThis.webpackChunkwebsite=globalThis.webpackChunkwebsite||[]).push([[31737],{45666:e=>{e.exports=JSON.parse('{"tag":{"label":"integrations","permalink":"/tags/integrations","allTagsPath":"/tags","count":24,"items":[{"id":"integrations/google-tag-manager-advanced","title":"Advanced GTM Integration","description":"Decouple Sealmetrics library load from the initial pageview using ?auto=0 and the buffer stub. Pass dynamic content grouping from the dataLayer without losing hits or sending duplicates.","permalink":"/integrations/google-tag-manager-advanced"},{"id":"api/bigquery","title":"BigQuery Integration","description":"Sync Sealmetrics analytics to Google BigQuery with hourly or daily schedules, backfill options, and BI tool integration","permalink":"/api/bigquery"},{"id":"platform/settings/integrations/bigquery","title":"BigQuery Integration","description":"Export your Sealmetrics data to Google BigQuery for advanced analysis.","permalink":"/platform/settings/integrations/bigquery"},{"id":"platform/settings/integrations/looker-studio","title":"Data Studio Integration","description":"Connect Sealmetrics to Google Data Studio for custom dashboards and visual reports.","permalink":"/platform/settings/integrations/looker-studio"},{"id":"integrations/cms/drupal","title":"Drupal","description":"Install the Sealmetrics Drupal module (9, 10, and 11) via Composer or manually for cookieless analytics with form, search, and 404 error tracking.","permalink":"/integrations/cms/drupal"},{"id":"integrations/google-tag-manager","title":"Google Tag Manager Template","description":"Install Sealmetrics tracking on your website using the official Google Tag Manager template. Track pageviews, conversions, and microconversions without writing code.","permalink":"/integrations/google-tag-manager"},{"id":"integrations/tag-management/gtm-template","title":"GTM Container Template","description":"Ready-to-import Google Tag Manager container template with pre-configured Sealmetrics tags, triggers, and variables for pageviews and conversions.","permalink":"/integrations/tag-management/gtm-template"},{"id":"integrations/index","title":"Integrations Overview","description":"Connect Sealmetrics with your favorite platforms, frameworks, and tools","permalink":"/integrations/"},{"id":"integrations/cms/joomla","title":"Joomla","description":"Install the Sealmetrics Joomla plugin (4.x and 5.x) for cookieless analytics with form, newsletter, search, and 404 tracking \u2014 no consent banner needed.","permalink":"/integrations/cms/joomla"},{"id":"integrations/ecommerce/magento","title":"Magento 2","description":"Install the Sealmetrics Magento 2.4+ (Adobe Commerce) module via app/code for cookieless analytics with product, cart, checkout, and purchase tracking.","permalink":"/integrations/ecommerce/magento"},{"id":"integrations/mcp-server","title":"MCP Server for AI Assistants","description":"Connect Claude, ChatGPT, Cursor, Codex, and other AI assistants to your Sealmetrics analytics using the Model Context Protocol (MCP) \u2014 either the hosted remote server (one URL, no install) or the local npx server.","permalink":"/integrations/mcp-server"},{"id":"integrations/frameworks/nextjs","title":"Next.js","description":"Add cookieless analytics to Next.js with the @sealmetrics/nextjs package \u2014 a SealMetricsScript component for both App Router and Pages Router setups.","permalink":"/integrations/frameworks/nextjs"},{"id":"integrations/frameworks/nuxt","title":"Nuxt 3","description":"Add cookieless analytics to Nuxt 3 with the @sealmetrics/nuxt module \u2014 one entry in nuxt.config.ts auto-loads the tracker on every page, no cookies.","permalink":"/integrations/frameworks/nuxt"},{"id":"integrations/ecommerce/opencart","title":"OpenCart","description":"Install the Sealmetrics OpenCart extension (3.x/4.x OCMOD package) for cookieless store analytics with product view, cart, checkout, and purchase events.","permalink":"/integrations/ecommerce/opencart"},{"id":"integrations/ecommerce/prestashop","title":"PrestaShop","description":"Privacy-first, cookieless analytics for PrestaShop 1.7+ and 8.x stores","permalink":"/integrations/ecommerce/prestashop"},{"id":"faq/product","title":"Product Features","description":"Learn about reports, funnels, ROAS, real-time data, API access, first-party tracking, and integrations.","permalink":"/faq/product"},{"id":"integrations/frameworks/react","title":"React","description":"Add privacy-first analytics to React with the @sealmetrics/react NPM package \u2014 provider or script component, no cookies or consent banner needed.","permalink":"/integrations/frameworks/react"},{"id":"integrations/ecommerce/shopify","title":"Shopify","description":"Connect Sealmetrics to Shopify via the Pixel app and a theme app embed, with purchases confirmed server-side by webhook \u2014 cookieless funnel tracking.","permalink":"/integrations/ecommerce/shopify"},{"id":"integrations/website-builders/squarespace","title":"Squarespace","description":"Privacy-first, cookieless analytics for Squarespace websites and Squarespace Commerce","permalink":"/integrations/website-builders/squarespace"},{"id":"integrations/website-builders/webflow","title":"Webflow","description":"Add Sealmetrics cookieless analytics to Webflow by pasting a script in Project Settings > Custom Code, with automatic event and lead form tracking.","permalink":"/integrations/website-builders/webflow"},{"id":"platform/settings/integrations/webhooks","title":"Webhooks","description":"Send real-time Sealmetrics events to your own services via HTTP callbacks, configured through the API.","permalink":"/platform/settings/integrations/webhooks"},{"id":"integrations/website-builders/wix","title":"Wix","description":"Add Sealmetrics cookieless analytics to Wix sites and Wix Stores via Settings > Custom Code or an embed element, with automatic event tracking.","permalink":"/integrations/website-builders/wix"},{"id":"integrations/ecommerce/woocommerce","title":"WooCommerce","description":"Install the Sealmetrics WooCommerce plugin for cookieless tracking of the full e-commerce funnel \u2014 product views, cart, checkout, and purchase revenue.","permalink":"/integrations/ecommerce/woocommerce"},{"id":"integrations/cms/wordpress","title":"WordPress","description":"Install the Sealmetrics WordPress plugin for cookieless analytics with search, 404, and Contact Form 7 lead tracking \u2014 no consent banner required.","permalink":"/integrations/cms/wordpress"}],"unlisted":false}}')}}]);